from typing import List

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)

        vals = sorted(set(nums))
        rank = {v: i + 1 for i, v in enumerate(vals)}
        m = len(vals)

        cnt = [0] * (m + 2)
        sm = [0] * (m + 2)

        def update(i, val, delta):
            while i <= m:
                cnt[i] += delta
                sm[i] += val * delta
                i += i & -i

        def query_cnt(i):
            s = 0
            while i > 0:
                s += cnt[i]
                i -= i & -i
            return s

        def query_sm(i):
            s = 0
            while i > 0:
                s += sm[i]
                i -= i & -i
            return s

        LOG = 1
        while LOG * 2 <= m:
            LOG *= 2

        def find_kth(kk):
            i = 0
            bit = LOG
            remaining = kk
            while bit > 0:
                if i + bit <= m and cnt[i + bit] < remaining:
                    i += bit
                    remaining -= cnt[i]
                bit //= 2
            return i + 1

        costs = []
        total_sum = 0
        mid_pos = (x + 1) // 2

        for i in range(n):
            r = rank[nums[i]]
            update(r, nums[i], 1)
            total_sum += nums[i]
            if i >= x:
                ro = rank[nums[i - x]]
                update(ro, nums[i - x], -1)
                total_sum -= nums[i - x]
            if i >= x - 1:
                mr = find_kth(mid_pos)
                median = vals[mr - 1]
                lower_sum = query_sm(mr - 1)
                lower_cnt = query_cnt(mr - 1)
                cost = (median * lower_cnt - lower_sum
                        + (total_sum - lower_sum) - median * (x - lower_cnt))
                costs.append(cost)

        INF = float('inf')
        dp = [[0] * (k + 1) for _ in range(n + 1)]
        for p in range(n + 1):
            for j in range(1, k + 1):
                dp[p][j] = INF

        for p in range(1, n + 1):
            for j in range(1, k + 1):
                best = dp[p - 1][j]
                if p >= x:
                    prev_val = dp[p - x][j - 1]
                    if prev_val < INF:
                        cand = prev_val + costs[p - x]
                        if cand < best:
                            best = cand
                dp[p][j] = best

        return dp[n][k]
